CREATE TABLE extension_media_associations(id TEXT PRIMARY KEY,account TEXT NOT NULL REFERENCES accounts(account),message_id TEXT NOT NULL REFERENCES messages(id),local_revision INTEGER NOT NULL,policy_generation INTEGER NOT NULL,content_hash TEXT NOT NULL,source_expires_at INTEGER NOT NULL DEFAULT 0,ordinal INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('image','voice')),protocol_reference BLOB NOT NULL,mime_type TEXT NOT NULL DEFAULT '',declared_bytes INTEGER NOT NULL CHECK(declared_bytes>=0),view_once INTEGER NOT NULL DEFAULT 0,availability TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,artifact_id TEXT NOT NULL DEFAULT '',UNIQUE(message_id,local_revision,ordinal));
CREATE INDEX extension_media_source ON extension_media_associations(message_id,active);
CREATE INDEX extension_media_artifact_links ON extension_media_associations(artifact_id,active);
CREATE TABLE extension_media_artifacts(id TEXT PRIMARY KEY,reservation_id TEXT NOT NULL UNIQUE,media_id TEXT NOT NULL REFERENCES extension_media_associations(id),account TEXT NOT NULL,message_id TEXT NOT NULL,local_revision INTEGER NOT NULL,policy_generation INTEGER NOT NULL,content_hash TEXT NOT NULL,source_expires_at INTEGER NOT NULL DEFAULT 0,budget TEXT NOT NULL CHECK(budget IN ('originals','decoded_work')),maximum_bytes INTEGER NOT NULL CHECK(maximum_bytes>0),charged_bytes INTEGER NOT NULL CHECK(charged_bytes>=0),lease_id TEXT NOT NULL,lease_until INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('reserved','staged','retained','evicting')),sha256 TEXT NOT NULL DEFAULT '',bytes INTEGER NOT NULL DEFAULT 0,actual_format TEXT NOT NULL DEFAULT '',cleanup_lease TEXT NOT NULL DEFAULT '',cleanup_ack INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,input_artifact_id TEXT NOT NULL DEFAULT '');
CREATE INDEX extension_media_budget ON extension_media_artifacts(budget,cleanup_ack);
CREATE INDEX extension_media_reservations ON extension_media_artifacts(media_id,cleanup_ack);
CREATE INDEX extension_media_input_pins ON extension_media_artifacts(input_artifact_id,budget,cleanup_ack);
